use axum::{
    extract::FromRequestParts,
    http::{request::Parts, StatusCode},
    response::{IntoResponse, Response},
    Json,
};
use loco_rs::{app::AppContext, auth::jwt};
use sea_orm::DbErr;
use serde::Serialize;
use serde_json::json;

use crate::models::users;

pub type ApiResult = std::result::Result<Response, ApiError>;

pub struct ApiError {
    status: StatusCode,
    field: &'static str,
    message: &'static str,
}

impl ApiError {
    pub fn new(status: StatusCode, field: &'static str, message: &'static str) -> Self {
        Self {
            status,
            field,
            message,
        }
    }
    pub fn blank(field: &'static str) -> Self {
        Self::new(StatusCode::UNPROCESSABLE_ENTITY, field, "can't be blank")
    }
    pub fn invalid(field: &'static str) -> Self {
        Self::new(StatusCode::UNPROCESSABLE_ENTITY, field, "is invalid")
    }
    pub fn taken(field: &'static str) -> Self {
        Self::new(StatusCode::CONFLICT, field, "has already been taken")
    }
    pub fn missing(field: &'static str) -> Self {
        Self::new(StatusCode::NOT_FOUND, field, "not found")
    }
    pub fn forbidden(field: &'static str) -> Self {
        Self::new(StatusCode::FORBIDDEN, field, "forbidden")
    }
}

impl From<DbErr> for ApiError {
    fn from(_: DbErr) -> Self {
        Self::new(StatusCode::INTERNAL_SERVER_ERROR, "server", "error")
    }
}

impl From<loco_rs::model::ModelError> for ApiError {
    fn from(_: loco_rs::model::ModelError) -> Self {
        Self::new(StatusCode::INTERNAL_SERVER_ERROR, "server", "error")
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        (
            self.status,
            Json(json!({"errors": {self.field: [self.message]}})),
        )
            .into_response()
    }
}

pub fn json_response<T: Serialize>(status: StatusCode, value: T) -> Response {
    (status, Json(value)).into_response()
}

pub fn required(value: &str, field: &'static str) -> std::result::Result<(), ApiError> {
    if value.trim().is_empty() {
        Err(ApiError::blank(field))
    } else {
        Ok(())
    }
}

pub struct Viewer(pub users::Model);
pub struct OptionalViewer(pub Option<users::Model>);

impl FromRequestParts<AppContext> for OptionalViewer {
    type Rejection = ApiError;

    async fn from_request_parts(
        parts: &mut Parts,
        ctx: &AppContext,
    ) -> std::result::Result<Self, Self::Rejection> {
        let Some(header) = parts.headers.get(axum::http::header::AUTHORIZATION) else {
            return Ok(Self(None));
        };
        let token = header
            .to_str()
            .ok()
            .and_then(|value| value.strip_prefix("Token "))
            .ok_or(ApiError::new(
                StatusCode::UNAUTHORIZED,
                "token",
                "is invalid",
            ))?;
        let config = ctx
            .config
            .get_jwt_config()
            .map_err(|_| ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, "server", "error"))?;
        let claims = jwt::JWT::new(&config.secret)
            .validate(token)
            .map_err(|_| ApiError::new(StatusCode::UNAUTHORIZED, "token", "is invalid"))?;
        let user = users::Model::by_pid(&ctx.db, &claims.claims.pid).await?;
        Ok(Self(user))
    }
}

impl FromRequestParts<AppContext> for Viewer {
    type Rejection = ApiError;

    async fn from_request_parts(
        parts: &mut Parts,
        ctx: &AppContext,
    ) -> std::result::Result<Self, Self::Rejection> {
        let OptionalViewer(user) = OptionalViewer::from_request_parts(parts, ctx).await?;
        user.map(Self).ok_or(ApiError::new(
            StatusCode::UNAUTHORIZED,
            "token",
            "is missing",
        ))
    }
}

use axum::{
    extract::{Json, Path, Query, State},
    http::StatusCode,
};
use loco_rs::prelude::*;
use serde::Deserialize;
use serde_json::{json, Value};

use crate::{
    controllers::api::{self, ApiError, ApiResult, OptionalViewer, Viewer},
    models::{articles, favorites, users},
    views::realworld::ArticleView,
};

#[derive(Default, Deserialize)]
pub struct ListQuery {
    tag: Option<String>,
    author: Option<String>,
    favorited: Option<String>,
    limit: Option<usize>,
    offset: Option<usize>,
}

#[derive(Deserialize)]
struct Envelope<T> {
    article: T,
}

#[derive(Deserialize)]
struct NewArticle {
    #[serde(default)]
    title: String,
    #[serde(default)]
    description: String,
    #[serde(default)]
    body: String,
    #[serde(default, rename = "tagList")]
    tag_list: Vec<String>,
}

pub async fn find(ctx: &AppContext, slug: &str) -> std::result::Result<articles::Model, ApiError> {
    articles::Model::by_slug(&ctx.db, slug)
        .await?
        .ok_or(ApiError::missing("article"))
}

async fn single(
    ctx: &AppContext,
    article: &articles::Model,
    viewer: Option<&users::Model>,
    status: StatusCode,
) -> ApiResult {
    let article = ArticleView::load(&ctx.db, article, viewer, true).await?;
    Ok(api::json_response(status, json!({"article": article})))
}

async fn list_response(
    ctx: &AppContext,
    viewer: Option<&users::Model>,
    query: ListQuery,
    feed: bool,
) -> ApiResult {
    let author = if let Some(name) = query.author.as_deref() {
        match users::Model::by_username(&ctx.db, name).await? {
            Some(user) => Some(user.id),
            None => {
                return Ok(api::json_response(
                    StatusCode::OK,
                    json!({"articles": [], "articlesCount": 0}),
                ))
            }
        }
    } else {
        None
    };
    let favorited = if let Some(name) = query.favorited.as_deref() {
        match users::Model::by_username(&ctx.db, name).await? {
            Some(user) => Some(user.id),
            None => {
                return Ok(api::json_response(
                    StatusCode::OK,
                    json!({"articles": [], "articlesCount": 0}),
                ))
            }
        }
    } else {
        None
    };
    let (articles, count) = articles::Model::list(
        &ctx.db,
        author,
        favorited,
        query.tag.as_deref(),
        if feed { viewer.map(|u| u.id) } else { None },
        query.limit.unwrap_or(20),
        query.offset.unwrap_or(0),
    )
    .await?;
    let mut views = Vec::new();
    for article in &articles {
        views.push(ArticleView::load(&ctx.db, article, viewer, false).await?);
    }
    Ok(api::json_response(
        StatusCode::OK,
        json!({"articles": views, "articlesCount": count}),
    ))
}

#[debug_handler]
async fn list(
    OptionalViewer(viewer): OptionalViewer,
    State(ctx): State<AppContext>,
    Query(query): Query<ListQuery>,
) -> ApiResult {
    list_response(&ctx, viewer.as_ref(), query, false).await
}

#[debug_handler]
async fn feed(
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
    Query(query): Query<ListQuery>,
) -> ApiResult {
    list_response(&ctx, Some(&viewer), query, true).await
}

#[debug_handler]
async fn show(
    Path(slug): Path<String>,
    OptionalViewer(viewer): OptionalViewer,
    State(ctx): State<AppContext>,
) -> ApiResult {
    let article = find(&ctx, &slug).await?;
    single(&ctx, &article, viewer.as_ref(), StatusCode::OK).await
}

#[debug_handler]
async fn create(
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
    Json(Envelope { article }): Json<Envelope<NewArticle>>,
) -> ApiResult {
    api::required(&article.title, "title")?;
    api::required(&article.description, "description")?;
    api::required(&article.body, "body")?;
    let article = articles::Model::create(
        &ctx.db,
        viewer.id,
        article.title,
        article.description,
        article.body,
        article.tag_list,
    )
    .await?;
    single(&ctx, &article, Some(&viewer), StatusCode::CREATED).await
}

fn changed_text(
    changes: &Value,
    field: &'static str,
) -> std::result::Result<Option<String>, ApiError> {
    changes
        .get(field)
        .map(|value| {
            let text = value.as_str().ok_or(ApiError::blank(field))?;
            api::required(text, field)?;
            Ok(text.to_owned())
        })
        .transpose()
}

#[debug_handler]
async fn update(
    Path(slug): Path<String>,
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
    Json(Envelope { article: changes }): Json<Envelope<Value>>,
) -> ApiResult {
    let article = find(&ctx, &slug).await?;
    if article.author_id != viewer.id {
        return Err(ApiError::forbidden("article"));
    }
    let mut active = article.into_active_model();
    if let Some(title) = changed_text(&changes, "title")? {
        active.slug = Set(articles::Model::slug_for(&title));
        active.title = Set(title);
    }
    if let Some(description) = changed_text(&changes, "description")? {
        active.description = Set(description);
    }
    if let Some(body) = changed_text(&changes, "body")? {
        active.body = Set(body);
    }
    if let Some(tags) = changes.get("tagList") {
        let tags: Vec<String> =
            serde_json::from_value(tags.clone()).map_err(|_| ApiError::invalid("tagList"))?;
        active = active.replace_tags(tags);
    }
    let article = active.update(&ctx.db).await?;
    single(&ctx, &article, Some(&viewer), StatusCode::OK).await
}

#[debug_handler]
async fn remove(
    Path(slug): Path<String>,
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
) -> ApiResult {
    let article = find(&ctx, &slug).await?;
    if article.author_id != viewer.id {
        return Err(ApiError::forbidden("article"));
    }
    article.delete(&ctx.db).await?;
    Ok(StatusCode::NO_CONTENT.into_response())
}

#[debug_handler]
async fn favorite(
    Path(slug): Path<String>,
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
) -> ApiResult {
    let article = find(&ctx, &slug).await?;
    favorites::Model::set(&ctx.db, viewer.id, article.id, true).await?;
    single(&ctx, &article, Some(&viewer), StatusCode::OK).await
}

#[debug_handler]
async fn unfavorite(
    Path(slug): Path<String>,
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
) -> ApiResult {
    let article = find(&ctx, &slug).await?;
    favorites::Model::set(&ctx.db, viewer.id, article.id, false).await?;
    single(&ctx, &article, Some(&viewer), StatusCode::OK).await
}

#[debug_handler]
async fn tags(State(ctx): State<AppContext>) -> ApiResult {
    let tags = articles::Model::all_tags(&ctx.db).await?;
    Ok(api::json_response(StatusCode::OK, json!({"tags": tags})))
}

pub fn routes() -> Routes {
    Routes::new()
        .prefix("/api")
        .add("/articles", get(list))
        .add("/articles", post(create))
        .add("/articles/feed", get(feed))
        .add("/articles/{slug}", get(show))
        .add("/articles/{slug}", put(update))
        .add("/articles/{slug}", delete(remove))
        .add("/articles/{slug}/favorite", post(favorite))
        .add("/articles/{slug}/favorite", delete(unfavorite))
        .add("/tags", get(tags))
}

use axum::{
    extract::{Json, Path, State},
    http::StatusCode,
    response::IntoResponse,
};
use loco_rs::prelude::*;
use serde::Deserialize;
use serde_json::json;

use crate::{
    controllers::{
        api::{self, ApiError, ApiResult, OptionalViewer, Viewer},
        articles,
    },
    models::comments,
    views::realworld::CommentView,
};

#[derive(Deserialize)]
struct Envelope<T> {
    comment: T,
}

#[derive(Deserialize)]
struct NewComment {
    #[serde(default)]
    body: String,
}

#[debug_handler]
async fn list(
    Path(slug): Path<String>,
    OptionalViewer(viewer): OptionalViewer,
    State(ctx): State<AppContext>,
) -> ApiResult {
    let article = articles::find(&ctx, &slug).await?;
    let comments = comments::Model::for_article(&ctx.db, article.id).await?;
    let mut views = Vec::new();
    for comment in &comments {
        views.push(CommentView::load(&ctx.db, comment, viewer.as_ref()).await?);
    }
    Ok(api::json_response(
        StatusCode::OK,
        json!({"comments": views}),
    ))
}

#[debug_handler]
async fn create(
    Path(slug): Path<String>,
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
    Json(Envelope { comment }): Json<Envelope<NewComment>>,
) -> ApiResult {
    let article = articles::find(&ctx, &slug).await?;
    api::required(&comment.body, "body")?;
    let comment = comments::Model::add(&ctx.db, article.id, viewer.id, comment.body).await?;
    let view = CommentView::load(&ctx.db, &comment, Some(&viewer)).await?;
    Ok(api::json_response(
        StatusCode::CREATED,
        json!({"comment": view}),
    ))
}

#[debug_handler]
async fn remove(
    Path((slug, id)): Path<(String, i64)>,
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
) -> ApiResult {
    let article = articles::find(&ctx, &slug).await?;
    let comment = comments::Entity::find_by_id(id)
        .one(&ctx.db)
        .await?
        .filter(|comment| comment.article_id == article.id)
        .ok_or(ApiError::missing("comment"))?;
    if comment.author_id != viewer.id {
        return Err(ApiError::forbidden("comment"));
    }
    comment.delete(&ctx.db).await?;
    Ok(StatusCode::NO_CONTENT.into_response())
}

pub fn routes() -> Routes {
    Routes::new()
        .prefix("/api/articles/{slug}/comments")
        .add("/", get(list))
        .add("/", post(create))
        .add("/{id}", delete(remove))
}

