#[derive(Deserialize)]
struct Envelope<T> {
    user: T,
}

#[derive(Deserialize)]
struct Registration {
    #[serde(default)]
    username: String,
    #[serde(default)]
    email: String,
    #[serde(default)]
    password: String,
}

#[derive(Deserialize)]
struct Login {
    #[serde(default)]
    email: String,
    #[serde(default)]
    password: String,
}

fn response(ctx: &AppContext, user: &users::Model, status: StatusCode) -> ApiResult {
    let config = ctx
        .config
        .get_jwt_config()
        .map_err(|_| ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, "server", "error"))?;
    let token = user.token(&config.secret, config.expiration)?;
    Ok(api::json_response(
        status,
        json!({"user": UserView::new(user, token)}),
    ))
}

#[debug_handler]
async fn register(
    State(ctx): State<AppContext>,
    Json(Envelope { user }): Json<Envelope<Registration>>,
) -> ApiResult {
    api::required(&user.username, "username")?;
    api::required(&user.email, "email")?;
    api::required(&user.password, "password")?;
    if users::Model::by_username(&ctx.db, &user.username)
        .await?
        .is_some()
    {
        return Err(ApiError::taken("username"));
    }
    if users::Model::by_email(&ctx.db, &user.email)
        .await?
        .is_some()
    {
        return Err(ApiError::taken("email"));
    }
    let user = users::Model::register(&ctx.db, user.username, user.email, user.password).await?;
    response(&ctx, &user, StatusCode::CREATED)
}

#[debug_handler]
async fn login(
    State(ctx): State<AppContext>,
    Json(Envelope { user }): Json<Envelope<Login>>,
) -> ApiResult {
    api::required(&user.email, "email")?;
    api::required(&user.password, "password")?;
    let user = users::Model::by_email(&ctx.db, &user.email)
        .await?
        .filter(|record| record.verify_password(&user.password))
        .ok_or(ApiError::new(
            StatusCode::UNAUTHORIZED,
            "credentials",
            "invalid",
        ))?;
    response(&ctx, &user, StatusCode::OK)
}

#[debug_handler]
async fn current(Viewer(user): Viewer, State(ctx): State<AppContext>) -> ApiResult {
    response(&ctx, &user, StatusCode::OK)
}

fn text_update(value: &Value, field: &'static str) -> std::result::Result<String, ApiError> {
    let text = value.as_str().ok_or(ApiError::blank(field))?;
    api::required(text, field)?;
    Ok(text.to_owned())
}

#[debug_handler]
async fn update(
    Viewer(user): Viewer,
    State(ctx): State<AppContext>,
    Json(Envelope { user: changes }): Json<Envelope<Value>>,
) -> ApiResult {
    let mut active = user.clone().into_active_model();
    if let Some(value) = changes.get("username") {
        let username = text_update(value, "username")?;
        if username != user.username
            && users::Model::by_username(&ctx.db, &username)
                .await?
                .is_some()
        {
            return Err(ApiError::taken("username"));
        }
        active.username = Set(username);
    }
    if let Some(value) = changes.get("email") {
        let email = text_update(value, "email")?;
        if email != user.email && users::Model::by_email(&ctx.db, &email).await?.is_some() {
            return Err(ApiError::taken("email"));
        }
        active.email = Set(email);
    }
    for (field, slot) in [("bio", &mut active.bio), ("image", &mut active.image)] {
        if let Some(value) = changes.get(field) {
            let text = match value {
                Value::Null => None,
                Value::String(text) if text.is_empty() => None,
                Value::String(text) => Some(text.clone()),
                _ => return Err(ApiError::invalid(field)),
            };
            *slot = Set(text);
        }
    }
    if let Some(value) = changes.get("password") {
        let password = text_update(value, "password")?;
        if password.len() < 8 {
            return Err(ApiError::invalid("password"));
        }
        let saved = active.change_password(&ctx.db, &password).await?;
        return response(&ctx, &saved, StatusCode::OK);
    }
    let saved = active.update(&ctx.db).await?;
    response(&ctx, &saved, StatusCode::OK)
}

pub fn routes() -> Routes {
    Routes::new()
        .prefix("/api")
        .add("/users", post(register))
        .add("/users/login", post(login))
        .add("/user", get(current))
        .add("/user", put(update))
}

use std::collections::BTreeSet;

use chrono::Utc;
use loco_rs::prelude::*;
use serde_json::Value;
use uuid::Uuid;

pub use super::_entities::articles::{self, ActiveModel, Entity, Model};

#[async_trait::async_trait]
impl ActiveModelBehavior for ActiveModel {
    async fn before_save<C>(mut self, _db: &C, insert: bool) -> std::result::Result<Self, DbErr>
    where
        C: ConnectionTrait,
    {
        if !insert {
            self.updated_at = Set(Utc::now().into());
        }
        Ok(self)
    }
}

impl Model {
    pub async fn by_slug(
        db: &DatabaseConnection,
        slug: &str,
    ) -> std::result::Result<Option<Self>, DbErr> {
        Entity::find()
            .filter(articles::Column::Slug.eq(slug))
            .one(db)
            .await
    }

    pub async fn create(
        db: &DatabaseConnection,
        author_id: i64,
        title: String,
        description: String,
        body: String,
        tags: Vec<String>,
    ) -> std::result::Result<Self, DbErr> {
        ActiveModel {
            slug: Set(Self::slug_for(&title)),
            title: Set(title),
            description: Set(description),
            body: Set(body),
            tag_list: Set(serde_json::json!(tags)),
            author_id: Set(author_id),
            ..Default::default()
        }
        .insert(db)
        .await
    }

    pub fn tags(&self) -> Vec<String> {
        serde_json::from_value(self.tag_list.clone()).unwrap_or_default()
    }

    pub fn slug_for(title: &str) -> String {
        format!("{}-{}", slug::slugify(title), Uuid::new_v4().simple())
    }

    pub async fn list(
        db: &DatabaseConnection,
        author: Option<i64>,
        favorited: Option<i64>,
        tag: Option<&str>,
        feed: Option<i64>,
        limit: usize,
        offset: usize,
    ) -> std::result::Result<(Vec<Self>, usize), DbErr> {
        use super::favorites;
        use super::follows;
        let mut query = Entity::find().order_by_desc(articles::Column::Id);
        if let Some(author) = author {
            query = query.filter(articles::Column::AuthorId.eq(author));
        }
        if let Some(user_id) = favorited {
            let ids: Vec<i64> = favorites::Entity::find()
                .filter(favorites::Column::UserId.eq(user_id))
                .all(db)
                .await?
                .into_iter()
                .map(|f| f.article_id)
                .collect();
            if ids.is_empty() {
                return Ok((Vec::new(), 0));
            }
            query = query.filter(articles::Column::Id.is_in(ids));
        }
        if let Some(user_id) = feed {
            let ids: Vec<i64> = follows::Entity::find()
                .filter(follows::Column::FollowerId.eq(user_id))
                .all(db)
                .await?
                .into_iter()
                .map(|f| f.followed_id)
                .collect();
            if ids.is_empty() {
                return Ok((Vec::new(), 0));
            }
            query = query.filter(articles::Column::AuthorId.is_in(ids));
        }
        if let Some(tag) = tag {
            let mut articles = query.all(db).await?;
            articles.retain(|article| article.tags().iter().any(|item| item == tag));
            let count = articles.len();
            return Ok((
                articles.into_iter().skip(offset).take(limit).collect(),
                count,
            ));
        }
        let count = query.clone().count(db).await? as usize;
        let articles = query
            .offset(offset as u64)
            .limit(limit as u64)
            .all(db)
            .await?;
        Ok((articles, count))
    }

    pub async fn all_tags(db: &DatabaseConnection) -> std::result::Result<BTreeSet<String>, DbErr> {
        Ok(Entity::find()
            .all(db)
            .await?
            .iter()
            .flat_map(Self::tags)
            .collect())
    }
}

impl ActiveModel {
    pub fn replace_tags(mut self, tags: Vec<String>) -> Self {
        self.tag_list = Set(Value::from(tags));
        self
    }
}

use loco_rs::{auth::jwt, hash, prelude::*};
use serde_json::Map;
use uuid::Uuid;

pub use super::_entities::users::{self, ActiveModel, Entity, Model};

#[async_trait::async_trait]
impl ActiveModelBehavior for ActiveModel {
    async fn before_save<C>(mut self, _db: &C, insert: bool) -> std::result::Result<Self, DbErr>
    where
        C: ConnectionTrait,
    {
        if insert {
            self.pid = Set(Uuid::new_v4());
        }
        Ok(self)
    }
}

impl Model {
    pub async fn by_username(
        db: &DatabaseConnection,
        username: &str,
    ) -> std::result::Result<Option<Self>, DbErr> {
        Entity::find()
            .filter(users::Column::Username.eq(username))
            .one(db)
            .await
    }

    pub async fn by_email(
        db: &DatabaseConnection,
        email: &str,
    ) -> std::result::Result<Option<Self>, DbErr> {
        Entity::find()
            .filter(users::Column::Email.eq(email))
            .one(db)
            .await
    }

    pub async fn by_pid(
        db: &DatabaseConnection,
        pid: &str,
    ) -> std::result::Result<Option<Self>, DbErr> {
        let Ok(pid) = Uuid::parse_str(pid) else {
            return Ok(None);
        };
        Entity::find()
            .filter(users::Column::Pid.eq(pid))
            .one(db)
            .await
    }

    pub async fn register(
        db: &DatabaseConnection,
        username: String,
        email: String,
        password: String,
    ) -> ModelResult<Self> {
        let password = hash::hash_password(&password).map_err(|e| ModelError::Any(e.into()))?;
        Ok(ActiveModel {
            username: Set(username),
            email: Set(email),
            password: Set(password),
            ..Default::default()
        }
        .insert(db)
        .await?)
    }

    pub fn token(&self, secret: &str, expiration: u64) -> ModelResult<String> {
        jwt::JWT::new(secret)
            .generate_token(expiration, self.pid.to_string(), Map::new())
            .map_err(ModelError::from)
    }

    pub fn verify_password(&self, password: &str) -> bool {
        hash::verify_password(password, &self.password)
    }
}

impl ActiveModel {
    pub async fn change_password(
        mut self,
        db: &DatabaseConnection,
        password: &str,
    ) -> ModelResult<Model> {
        self.password = Set(hash::hash_password(password).map_err(|e| ModelError::Any(e.into()))?);
        Ok(self.update(db).await?)
    }
}

pub use super::_entities::favorites::{self, ActiveModel, Column, Entity, Model};
use loco_rs::prelude::*;
impl ActiveModelBehavior for ActiveModel {}

impl Model {
    pub async fn count(
        db: &DatabaseConnection,
        article_id: i64,
    ) -> std::result::Result<u64, DbErr> {
        Entity::find()
            .filter(favorites::Column::ArticleId.eq(article_id))
            .count(db)
            .await
    }

    pub async fn is_favorited(
        db: &DatabaseConnection,
        user_id: i64,
        article_id: i64,
    ) -> std::result::Result<bool, DbErr> {
        Ok(Entity::find()
            .filter(favorites::Column::UserId.eq(user_id))
            .filter(favorites::Column::ArticleId.eq(article_id))
            .one(db)
            .await?
            .is_some())
    }

    pub async fn set(
        db: &DatabaseConnection,
        user_id: i64,
        article_id: i64,
        favorited: bool,
    ) -> std::result::Result<(), DbErr> {
        if favorited {
            Entity::insert(ActiveModel {
                user_id: Set(user_id),
                article_id: Set(article_id),
                ..Default::default()
            })
            .on_conflict_do_nothing_on([Column::UserId, Column::ArticleId])
            .exec(db)
            .await?;
        } else {
            Entity::delete_many()
                .filter(Column::UserId.eq(user_id))
                .filter(Column::ArticleId.eq(article_id))
                .exec(db)
                .await?;
        }
        Ok(())
    }
}

use loco_rs::prelude::*;
use serde::Serialize;

use crate::models::{articles, comments, favorites, follows, users};

#[derive(Serialize)]
pub struct UserView {
    pub email: String,
    pub token: String,
    pub username: String,
    pub bio: Option<String>,
    pub image: Option<String>,
}

impl UserView {
    pub fn new(user: &users::Model, token: String) -> Self {
        Self {
            email: user.email.clone(),
            token,
            username: user.username.clone(),
            bio: user.bio.clone(),
            image: user.image.clone(),
        }
    }
}

#[derive(Serialize)]
pub struct ProfileView {
    pub username: String,
    pub bio: Option<String>,
    pub image: Option<String>,
    pub following: bool,
}

impl ProfileView {
    pub async fn load(
        db: &DatabaseConnection,
        user: &users::Model,
        viewer: Option<&users::Model>,
    ) -> std::result::Result<Self, DbErr> {
        let following = if let Some(viewer) = viewer {
            follows::Model::is_following(db, viewer.id, user.id).await?
        } else {
            false
        };
        Ok(Self {
            username: user.username.clone(),
            bio: user.bio.clone(),
            image: user.image.clone(),
            following,
        })
    }
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ArticleView {
    pub slug: String,
    pub title: String,
    pub description: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub body: Option<String>,
    pub tag_list: Vec<String>,
    pub created_at: String,
    pub updated_at: String,
    pub favorited: bool,
    pub favorites_count: u64,
    pub author: ProfileView,
}

impl ArticleView {
    pub async fn load(
        db: &DatabaseConnection,
        article: &articles::Model,
        viewer: Option<&users::Model>,
        include_body: bool,
    ) -> std::result::Result<Self, DbErr> {
        let author = users::Entity::find_by_id(article.author_id)
            .one(db)
            .await?
            .ok_or(DbErr::RecordNotFound("author".into()))?;
        let favorited = if let Some(viewer) = viewer {
            favorites::Model::is_favorited(db, viewer.id, article.id).await?
        } else {
            false
        };
        Ok(Self {
            slug: article.slug.clone(),
            title: article.title.clone(),
            description: article.description.clone(),
            body: include_body.then(|| article.body.clone()),
            tag_list: article.tags(),
            created_at: article.created_at.to_rfc3339(),
            updated_at: article.updated_at.to_rfc3339(),
            favorited,
            favorites_count: favorites::Model::count(db, article.id).await?,
            author: ProfileView::load(db, &author, viewer).await?,
        })
    }
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CommentView {
    pub id: i64,
    pub created_at: String,
    pub updated_at: String,
    pub body: String,
    pub author: ProfileView,
}

impl CommentView {
    pub async fn load(
        db: &DatabaseConnection,
        comment: &comments::Model,
        viewer: Option<&users::Model>,
    ) -> std::result::Result<Self, DbErr> {
        let author = users::Entity::find_by_id(comment.author_id)
            .one(db)
            .await?
            .ok_or(DbErr::RecordNotFound("author".into()))?;
        Ok(Self {
            id: comment.id,
            created_at: comment.created_at.to_rfc3339(),
            updated_at: comment.updated_at.to_rfc3339(),
            body: comment.body.clone(),
            author: ProfileView::load(db, &author, viewer).await?,
        })
    }
}

